findings.codeql_raw_query:
/**
 * @name Trace pickle.load source
 * @description Trace where the file object passed to pickle.load comes from
 * @kind path-problem
 * @problem.severity error
 * @id py/trace-pickle-source
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module PickleSourceConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Source is the return value of an open() call
    source = API::builtin("open").getACall()
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink is the argument to pickle.load
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember("load").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PickleSourceFlow = TaintTracking::Global<PickleSourceConfig>;
import PickleSourceFlow::PathGraph

from PickleSourceFlow::PathNode source, PickleSourceFlow::PathNode sink
where PickleSourceFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "pickle.load uses file from $@", source.getNode(), "open()"
